{-# LANGUAGE GHC2024 #-}
{-# LANGUAGE OverloadedStrings #-}
{-# LANGUAGE OverloadedRecordDot #-}
import Data.Aeson (object)
import Data.Time (UTCTime)
import Shikigami.Activity (ActivityEnvelope(..),Actor(..),Subject(..))
import Shikigami.Agent.Decl (AgentDecl(..))
import Shikigami.Agent.Loader (loadAgent)
import Shikigami.Agent.Name (mkAgentName)
import Shikigami.Agent.Run.Key (runKeyText)
import Shikigami.Agent.RunJob (RunJob(..),RunRouteKind(..))
import Shikigami.Trigger.Enqueue (addressedRunKey,addressedRunKeyWithKey,runJobFromEnvelope,scheduleRunIdempotencyKey)
import Shikigami.Trigger.RequestKey qualified as Addressed
main :: IO ()
main = do
 decl <- loadAgent "agents/heartbeat.dhall" >>= either (fail . show) pure
 heartbeat <- either (fail . show) pure (mkAgentName "heartbeat")
 risk <- either (fail . show) pure (mkAgentName "risk-agent")
 caller <- either (fail . show) pure (Addressed.parseRequestKey "shared")
 let due = read "2026-06-20 00:01:00 UTC" :: UTCTime
     envelope = ActivityEnvelope "act_stream_1" "2026-08-19T00:00:00Z" "shinzui/test" (Actor "service" "fixture" Nothing) (Subject "ticket" "ticket-1") "customer.risk_detected" (object []) [] "act_stream_1"
 print ("schedule",runKeyText (scheduleRunIdempotencyKey heartbeat due))
 print ("stream",runKeyText (runJobFromEnvelope due (decl {name=risk}) envelope).idempotencyKey)
 print ("addressed-payload",runKeyText (addressedRunKey heartbeat AgentWorkflowRoute (object [])))
 print ("addressed-caller",runKeyText (addressedRunKeyWithKey heartbeat AgentWorkflowRoute caller))
